CREATE TABLE public.cs_sync_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), origem text NOT NULL CHECK(origem IN ('agendado','manual')), iniciado_por uuid, status text NOT NULL CHECK(status IN ('executando','sucesso','falha','parcial')), iniciado_em timestamptz NOT NULL DEFAULT now(), concluido_em timestamptz, negocios_lidos integer NOT NULL DEFAULT 0, erro text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cs_sync_runs TO authenticated; GRANT ALL ON public.cs_sync_runs TO service_role;
ALTER TABLE public.cs_sync_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY cs_runs_read ON public.cs_sync_runs FOR SELECT TO authenticated USING(public.account_active());
CREATE TRIGGER cs_runs_updated BEFORE UPDATE ON public.cs_sync_runs FOR EACH ROW EXECUTE FUNCTION public.telegram_touch_updated();
CREATE TABLE public.cs_snapshot (deal_id bigint PRIMARY KEY, org_id bigint, titulo text NOT NULL, pipeline_id integer NOT NULL CHECK(pipeline_id IN (1,15,16)), stage_id integer NOT NULL, owner_id integer NOT NULL, owner_nome text, status text NOT NULL, valor numeric(18,2), perfil_conta text, ultimo_contato_efetivo date, ultima_reuniao_cs date, data_contratacao date, stage_change_time timestamptz, add_time timestamptz, proxima_atividade_data date, atividades_vencidas integer NOT NULL DEFAULT 0, sync_id uuid NOT NULL REFERENCES public.cs_sync_runs(id), atualizado_em timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cs_snapshot TO authenticated; GRANT ALL ON public.cs_snapshot TO service_role;
ALTER TABLE public.cs_snapshot ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.cs_pode_ver(owner_id integer, pipeline_id integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT $2 IN (1,15,16) AND EXISTS(SELECT 1 FROM public.account_access a JOIN public.profiles p ON p.id=a.user_id JOIN public.user_roles r ON r.user_id=p.id WHERE p.id=auth.uid() AND a.status='ativo' AND a.terms_accepted_at IS NOT NULL AND (r.role IN ('admin','superadmin') OR p.papel IN ('gestor','admin') OR (p.papel='cs' AND p.pipedrive_user_id=$1))) $$;
REVOKE ALL ON FUNCTION public.cs_pode_ver(integer,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cs_pode_ver(integer,integer) TO authenticated,service_role;
CREATE POLICY cs_snapshot_read ON public.cs_snapshot FOR SELECT TO authenticated USING(public.cs_pode_ver(owner_id,pipeline_id));
CREATE INDEX cs_snapshot_pipeline ON public.cs_snapshot(pipeline_id); CREATE INDEX cs_snapshot_owner ON public.cs_snapshot(owner_id); CREATE INDEX cs_snapshot_stage ON public.cs_snapshot(stage_id);
CREATE TRIGGER cs_snapshot_updated BEFORE UPDATE ON public.cs_snapshot FOR EACH ROW EXECUTE FUNCTION public.telegram_touch_updated();
CREATE TABLE public.cs_metricas_diarias (dia date NOT NULL, pipeline_id integer NOT NULL, owner_id integer NOT NULL, clientes_ativos integer NOT NULL, mrr numeric(18,2), cobertura_30 numeric, cobertura_60 numeric, cobertura_90 numeric, sem_contato_60 integer NOT NULL, atividades_vencidas integer NOT NULL, cancelados_dia integer NOT NULL, mrr_cancelado_dia numeric(18,2), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(dia,pipeline_id,owner_id));
GRANT SELECT ON public.cs_metricas_diarias TO authenticated; GRANT ALL ON public.cs_metricas_diarias TO service_role;
ALTER TABLE public.cs_metricas_diarias ENABLE ROW LEVEL SECURITY;
CREATE POLICY cs_metrics_read ON public.cs_metricas_diarias FOR SELECT TO authenticated USING(public.cs_pode_ver(owner_id,pipeline_id));
CREATE INDEX cs_metrics_pipeline ON public.cs_metricas_diarias(pipeline_id); CREATE INDEX cs_metrics_owner ON public.cs_metricas_diarias(owner_id);
CREATE TRIGGER cs_metrics_updated BEFORE UPDATE ON public.cs_metricas_diarias FOR EACH ROW EXECUTE FUNCTION public.telegram_touch_updated();
CREATE OR REPLACE FUNCTION public.cs_iniciar_sync(source text, actor uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE run uuid; BEGIN
PERFORM pg_advisory_xact_lock(841516);
IF source NOT IN ('manual','agendado') THEN RAISE EXCEPTION 'Origem inválida'; END IF;
IF source='manual' AND NOT EXISTS(SELECT 1 FROM public.account_access WHERE user_id=actor AND status='ativo' AND terms_accepted_at IS NOT NULL) THEN RAISE EXCEPTION 'Conta inativa'; END IF;
UPDATE public.cs_sync_runs SET status='falha',concluido_em=now(),erro='Tempo limite excedido; snapshot anterior preservado' WHERE status='executando' AND iniciado_em<now()-interval '30 minutes';
IF EXISTS(SELECT 1 FROM public.cs_sync_runs WHERE status='executando') THEN RAISE EXCEPTION 'Já existe uma atualização em andamento'; END IF;
IF source='manual' AND EXISTS(SELECT 1 FROM public.cs_sync_runs WHERE origem='manual' AND iniciado_em>now()-interval '10 minutes') THEN RAISE EXCEPTION 'Aguarde 10 minutos entre atualizações manuais'; END IF;
INSERT INTO public.cs_sync_runs(origem,iniciado_por,status) VALUES(source,actor,'executando') RETURNING id INTO run; RETURN run; END $$;
REVOKE ALL ON FUNCTION public.cs_iniciar_sync(text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cs_iniciar_sync(text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.cs_publicar_snapshot(run uuid, rows jsonb, lidos integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE dia_local date := (now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN
PERFORM pg_advisory_xact_lock(841516);
IF NOT EXISTS(SELECT 1 FROM public.cs_sync_runs WHERE id=run AND status='executando' FOR UPDATE) THEN RAISE EXCEPTION 'Atualização não está em execução'; END IF;
IF jsonb_typeof(rows)<>'array' OR lidos<jsonb_array_length(rows) THEN RAISE EXCEPTION 'Snapshot inválido'; END IF;
INSERT INTO public.cs_snapshot(deal_id,org_id,titulo,pipeline_id,stage_id,owner_id,owner_nome,status,valor,perfil_conta,ultimo_contato_efetivo,ultima_reuniao_cs,data_contratacao,stage_change_time,add_time,proxima_atividade_data,atividades_vencidas,sync_id,atualizado_em)
SELECT x.deal_id,x.org_id,x.titulo,x.pipeline_id,x.stage_id,x.owner_id,x.owner_nome,x.status,x.valor,x.perfil_conta,x.ultimo_contato_efetivo,x.ultima_reuniao_cs,x.data_contratacao,x.stage_change_time,x.add_time,x.proxima_atividade_data,x.atividades_vencidas,run,now() FROM jsonb_to_recordset(rows) AS x(deal_id bigint,org_id bigint,titulo text,pipeline_id integer,stage_id integer,owner_id integer,owner_nome text,status text,valor numeric,perfil_conta text,ultimo_contato_efetivo date,ultima_reuniao_cs date,data_contratacao date,stage_change_time timestamptz,add_time timestamptz,proxima_atividade_data date,atividades_vencidas integer)
ON CONFLICT(deal_id) DO UPDATE SET org_id=excluded.org_id,titulo=excluded.titulo,pipeline_id=excluded.pipeline_id,stage_id=excluded.stage_id,owner_id=excluded.owner_id,owner_nome=excluded.owner_nome,status=excluded.status,valor=excluded.valor,perfil_conta=excluded.perfil_conta,ultimo_contato_efetivo=excluded.ultimo_contato_efetivo,ultima_reuniao_cs=excluded.ultima_reuniao_cs,data_contratacao=excluded.data_contratacao,stage_change_time=excluded.stage_change_time,add_time=excluded.add_time,proxima_atividade_data=excluded.proxima_atividade_data,atividades_vencidas=excluded.atividades_vencidas,sync_id=run,atualizado_em=now();
DELETE FROM public.cs_snapshot WHERE sync_id<>run;
WITH donos AS (SELECT DISTINCT pipeline_id,owner_id FROM public.cs_snapshot), ativos AS (
SELECT pipeline_id,owner_id,coalesce('org:'||org_id::text,'deal:'||deal_id::text) cliente,CASE WHEN pipeline_id=1 THEN 0 ELSE CASE WHEN count(valor)=count(*) THEN sum(valor) ELSE NULL END END receita,max(ultimo_contato_efetivo) contato,sum(atividades_vencidas) vencidas FROM public.cs_snapshot WHERE status='open' AND stage_id NOT IN (105,111) GROUP BY pipeline_id,owner_id,coalesce('org:'||org_id::text,'deal:'||deal_id::text)), totais AS (
SELECT pipeline_id,owner_id,count(*)::integer clientes,CASE WHEN count(receita)=count(*) THEN sum(receita) ELSE NULL END mrr,count(*) FILTER(WHERE contato BETWEEN dia_local-30 AND dia_local)::numeric / nullif(count(*),0)*100 c30,count(*) FILTER(WHERE contato BETWEEN dia_local-60 AND dia_local)::numeric / nullif(count(*),0)*100 c60,count(*) FILTER(WHERE contato BETWEEN dia_local-90 AND dia_local)::numeric / nullif(count(*),0)*100 c90,count(*) FILTER(WHERE contato IS NULL OR contato<dia_local-60 OR contato>dia_local)::integer sem60,sum(vencidas)::integer vencidas FROM ativos GROUP BY pipeline_id,owner_id), cancel AS (
SELECT pipeline_id,owner_id,count(*)::integer n,CASE WHEN count(valor)=count(*) THEN sum(valor) ELSE NULL END receita FROM public.cs_snapshot WHERE stage_id IN (105,111) AND (stage_change_time AT TIME ZONE 'America/Sao_Paulo')::date=dia_local GROUP BY pipeline_id,owner_id)
INSERT INTO public.cs_metricas_diarias(dia,pipeline_id,owner_id,clientes_ativos,mrr,cobertura_30,cobertura_60,cobertura_90,sem_contato_60,atividades_vencidas,cancelados_dia,mrr_cancelado_dia)
SELECT dia_local,d.pipeline_id,d.owner_id,coalesce(t.clientes,0),CASE WHEN t.clientes IS NULL THEN 0 ELSE t.mrr END,t.c30,t.c60,t.c90,coalesce(t.sem60,0),coalesce(t.vencidas,0),coalesce(c.n,0),CASE WHEN c.n IS NULL THEN 0 ELSE c.receita END FROM donos d LEFT JOIN totais t USING(pipeline_id,owner_id) LEFT JOIN cancel c USING(pipeline_id,owner_id)
ON CONFLICT(dia,pipeline_id,owner_id) DO UPDATE SET clientes_ativos=excluded.clientes_ativos,mrr=excluded.mrr,cobertura_30=excluded.cobertura_30,cobertura_60=excluded.cobertura_60,cobertura_90=excluded.cobertura_90,sem_contato_60=excluded.sem_contato_60,atividades_vencidas=excluded.atividades_vencidas,cancelados_dia=excluded.cancelados_dia,mrr_cancelado_dia=excluded.mrr_cancelado_dia;
UPDATE public.cs_sync_runs SET status='sucesso',concluido_em=now(),negocios_lidos=lidos,erro=NULL WHERE id=run;
END $$;
REVOKE ALL ON FUNCTION public.cs_publicar_snapshot(uuid,jsonb,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cs_publicar_snapshot(uuid,jsonb,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.cs_atribuir_perfil(actor uuid,target uuid,papel_cs public.papel_usuario,owner integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.account_access a USING(user_id) WHERE r.user_id=actor AND r.role IN ('admin','superadmin') AND a.status='ativo' AND a.terms_accepted_at IS NOT NULL) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
IF owner IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.cs_snapshot WHERE owner_id=owner) THEN RAISE EXCEPTION 'Responsável não consta da sincronização'; END IF;
UPDATE public.profiles SET papel=papel_cs,pipedrive_user_id=owner WHERE id=target;
IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada'; END IF;
INSERT INTO public.audit_log(actor_id,target_id,action,details) VALUES(actor,target,'cs_profile',jsonb_build_object('papel',papel_cs,'owner_id',owner)); END $$;
REVOKE ALL ON FUNCTION public.cs_atribuir_perfil(uuid,uuid,public.papel_usuario,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cs_atribuir_perfil(uuid,uuid,public.papel_usuario,integer) TO service_role;
UPDATE public.profiles SET papel='admin',pipedrive_user_id=17273704 WHERE email='vinicius@crmcontent.com';